const SubscriptionAuditTable = (props) => {
  const {
    names = [],
    monthlyCosts = [],
    lastIncreaseBadges = [],
    usageEstimates = [],
    cancelSavingsMonthly = []
  } = props || {};

  const formatCurrency = (n) => {
    const num = Number(n);
    const safe = isNaN(num) ? 0 : num;
    return "$" + safe.toFixed(2);
  };

  const usageBadge = (level) => {
    const text = (level || "").toString().toLowerCase();
    const map = {
      low: "bg-green-100 text-green-700",
      medium: "bg-blue-100 text-blue-700",
      high: "bg-gray-100 text-gray-700"
    };
    const cls = map[text] || "bg-gray-100 text-gray-700";
    const label = text ? text.charAt(0).toUpperCase() + text.slice(1) : "Unknown";
    return (
      <span className={"px-2 py-1 text-xs font-medium rounded " + cls}>
        {label}
      </span>
    );
  };

  const increaseBadge = (txt) => {
    const label = txt || "No recent change";
    const cls = txt ? "bg-blue-50 text-blue-700" : "bg-gray-100 text-gray-700";
    return (
      <span className={"px-2 py-1 text-xs font-medium rounded " + cls}>
        {label}
      </span>
    );
  };

  const rowCount = Math.max(
    Array.isArray(names) ? names.length : 0,
    Array.isArray(monthlyCosts) ? monthlyCosts.length : 0,
    Array.isArray(lastIncreaseBadges) ? lastIncreaseBadges.length : 0,
    Array.isArray(usageEstimates) ? usageEstimates.length : 0,
    Array.isArray(cancelSavingsMonthly) ? cancelSavingsMonthly.length : 0
  );

  const rows = Array.from({ length: rowCount }).map((_, i) => {
    const name = Array.isArray(names) && names[i] ? names[i] : "Unnamed Subscription";
    const cost = Array.isArray(monthlyCosts) && typeof monthlyCosts[i] === "number" ? monthlyCosts[i] : 0;
    const inc = Array.isArray(lastIncreaseBadges) && lastIncreaseBadges[i] ? lastIncreaseBadges[i] : "";
    const usage = Array.isArray(usageEstimates) && usageEstimates[i] ? usageEstimates[i] : "";
    const save = Array.isArray(cancelSavingsMonthly) && typeof cancelSavingsMonthly[i] === "number" ? cancelSavingsMonthly[i] : 0;
    return { name, cost, inc, usage, save, idx: i };
  });

  const totals = rows.reduce(
    (acc, r) => {
      const c = isNaN(Number(r.cost)) ? 0 : Number(r.cost);
      const s = isNaN(Number(r.save)) ? 0 : Number(r.save);
      return { cost: acc.cost + c, save: acc.save + s };
    },
    { cost: 0, save: 0 }
  );

  return (
    <div className="w-full max-w-2xl mx-auto bg-white rounded-lg shadow-sm border border-gray-200 p-4 hover:shadow-md transition-shadow duration-200">
      <div className="flex items-start justify-between mb-3">
        <div>
          <h3 className="text-lg font-semibold text-gray-900">Subscription Audit</h3>
          <p className="text-sm text-gray-600">Overview of recurring costs and potential savings</p>
        </div>
        <div className="text-right">
          <div className="text-sm text-gray-600">Total Monthly Cost</div>
          <div className="text-base font-semibold text-gray-900">{formatCurrency(totals.cost)}</div>
        </div>
      </div>

      {rows.length === 0 ? (
        <div className="flex items-center gap-3 p-4 bg-gray-50 rounded-md">
          <span className="text-xl">🗂️</span>
          <div>
            <div className="text-sm font-medium text-gray-800">No subscriptions to display</div>
            <div className="text-xs text-gray-600">Provide subscription data to see audit details</div>
          </div>
        </div>
      ) : (
        <div className="overflow-x-auto rounded-md border border-gray-200">
          <table className="min-w-full divide-y divide-gray-200">
            <thead className="bg-gray-50">
              <tr>
                <th className="px-4 py-3 text-left text-xs font-medium text-gray-600 uppercase tracking-wider">Name</th>
                <th className="px-4 py-3 text-right text-xs font-medium text-gray-600 uppercase tracking-wider">Monthly Cost</th>
                <th className="px-4 py-3 text-left text-xs font-medium text-gray-600 uppercase tracking-wider">Last Increase</th>
                <th className="px-4 py-3 text-left text-xs font-medium text-gray-600 uppercase tracking-wider">Usage</th>
                <th className="px-4 py-3 text-right text-xs font-medium text-gray-600 uppercase tracking-wider">Cancel Savings/mo</th>
              </tr>
            </thead>
            <tbody className="bg-white divide-y divide-gray-100">
              {rows.map((row) => (
                <tr key={row.idx} className="hover:bg-gray-50">
                  <td className="px-4 py-3">
                    <div className="flex items-center">
                      <div className="flex-shrink-0 w-8 h-8 rounded-md bg-gray-100 flex items-center justify-center text-gray-500 text-sm mr-3">
                        {row.name ? row.name.charAt(0).toUpperCase() : "S"}
                      </div>
                      <div className="min-w-0">
                        <div className="text-sm font-medium text-gray-900 line-clamp-1">{row.name}</div>
                        <div className="text-xs text-gray-500">Recurring</div>
                      </div>
                    </div>
                  </td>
                  <td className="px-4 py-3 text-right text-sm text-gray-900 font-medium">{formatCurrency(row.cost)}</td>
                  <td className="px-4 py-3">
                    <div className="flex items-center gap-2">
                      {increaseBadge(row.inc)}
                    </div>
                  </td>
                  <td className="px-4 py-3">
                    <div className="flex items-center gap-2">
                      {usageBadge(row.usage)}
                    </div>
                  </td>
                  <td className="px-4 py-3 text-right">
                    <span className="text-sm font-semibold text-green-600">{formatCurrency(row.save)}</span>
                  </td>
                </tr>
              ))}
            </tbody>
            <tfoot className="bg-gray-50">
              <tr>
                <td className="px-4 py-3 text-sm font-medium text-gray-700">Totals</td>
                <td className="px-4 py-3 text-right text-sm font-semibold text-gray-900">{formatCurrency(totals.cost)}</td>
                <td className="px-4 py-3"></td>
                <td className="px-4 py-3"></td>
                <td className="px-4 py-3 text-right text-sm font-semibold text-green-700">{formatCurrency(totals.save)}</td>
              </tr>
            </tfoot>
          </table>
        </div>
      )}

      <div className="mt-4 grid grid-cols-1 sm:grid-cols-3 gap-3">
        <div className="p-3 bg-gray-50 rounded-md border border-gray-200">
          <div className="text-xs text-gray-600">Subscriptions</div>
          <div className="text-base font-semibold text-gray-900">{rows.length.toLocaleString()}</div>
        </div>
        <div className="p-3 bg-gray-50 rounded-md border border-gray-200">
          <div className="text-xs text-gray-600">Monthly Cost</div>
          <div className="text-base font-semibold text-gray-900">{formatCurrency(totals.cost)}</div>
        </div>
        <div className="p-3 bg-gray-50 rounded-md border border-gray-200">
          <div className="text-xs text-gray-600">Potential Annual Savings</div>
          <div className="text-base font-semibold text-green-700">{formatCurrency(totals.save * 12)}</div>
        </div>
