    </div>
  );
};

const AuditSummaryBar = (props) => {
  const {
    totalMonthlySpend,
    subscriptionCount,
    potentialSavingsMonthly,
    increasesCount,
    duplicatesCount,
  } = props || {};

  const spend = isNaN(Number(totalMonthlySpend)) ? null : Number(totalMonthlySpend);
  const subs = isNaN(Number(subscriptionCount)) ? null : Number(subscriptionCount);
  const savings = isNaN(Number(potentialSavingsMonthly)) ? null : Number(potentialSavingsMonthly);
  const inc = isNaN(Number(increasesCount)) ? null : Number(increasesCount);
  const dup = isNaN(Number(duplicatesCount)) ? null : Number(duplicatesCount);

  const hasData =
    (typeof spend === 'number' && !isNaN(spend)) ||
    (typeof subs === 'number' && !isNaN(subs)) ||
    (typeof savings === 'number' && !isNaN(savings)) ||
    (typeof inc === 'number' && !isNaN(inc)) ||
    (typeof dup === 'number' && !isNaN(dup));

  const currency = (n) => {
    const num = Number(n);
    if (isNaN(num)) return '—';
    try {
      return new Intl.NumberFormat(undefined, { style: 'currency', currency: 'USD', maximumFractionDigits: 0 }).format(num);
    } catch (e) {
      return '$' + num.toLocaleString();
    }
  };

  const formatCount = (n) => {
    const num = Number(n);
    return isNaN(num) ? '—' : num.toLocaleString();
  };

  const savingsPct = (() => {
    if (typeof spend === 'number' && spend > 0 && typeof savings === 'number' && savings >= 0) {
      const pct = Math.min(100, Math.max(0, (savings / spend) * 100));
      return pct;
    }
    return 0;
  })();

  if (!hasData) {
    return (
      <div className="w-full max-w-2xl mx-auto bg-white border border-gray-200 rounded-lg p-6 shadow-sm text-center">
        <div className="mx-auto mb-2 text-3xl">🗂️</div>
        <div className="text-lg font-semibold text-gray-900">Audit Summary</div>
        <div className="mt-1 text-sm text-gray-600">No audit data available</div>
      </div>
    );
  }

  return (
    <div className="w-full max-w-2xl mx-auto bg-white border border-gray-200 rounded-lg p-6 shadow-sm hover:shadow-md transition-shadow">
      <div className="flex items-start justify-between mb-4">
        <div>
          <div className="text-lg font-semibold text-gray-900">Audit Summary</div>
          <div className="text-sm text-gray-600">Snapshot of your subscription spend</div>
        </div>
        <div className="px-3 py-1 rounded-md bg-blue-50 text-blue-700 text-sm font-medium">
          Total Spend: {currency(spend)}/mo
        </div>
      </div>

      <div className="grid grid-cols-1 sm:grid-cols-2 gap-4 mb-4">
        <div className="p-4 rounded-lg border border-gray-100 bg-gray-50">
          <div className="flex items-center justify-between mb-1">
            <span className="text-sm font-medium text-gray-700">Potential Savings</span>
            <span className="px-2 py-0.5 text-xs font-medium bg-green-100 text-green-700 rounded">
              {savingsPct ? Math.round(savingsPct) : 0}% of spend
            </span>
          </div>
          <div className="text-xl font-semibold text-green-700">{currency(savings)}/mo</div>
          <div className="mt-3">
            <div className="w-full h-2 bg-gray-200 rounded">
              <div
                className="h-2 bg-green-500 rounded"
                style={{ width: savingsPct + '%' }}
              />
            </div>
          </div>
        </div>

        <div className="p-4 rounded-lg border border-gray-100 bg-gray-50">
          <div className="flex items-center justify-between mb-1">
            <span className="text-sm font-medium text-gray-700">Subscriptions</span>
            <span className="text-xs text-gray-500">Active</span>
          </div>
          <div className="text-xl font-semibold text-gray-900">{formatCount(subs)}</div>
          <div className="mt-1 text-xs text-gray-500">Tracked in this audit</div>
        </div>
      </div>

      <div className="grid grid-cols-1 sm:grid-cols-3 gap-4">
        <div className="p-3 rounded-lg border border-gray-100">
          <div className="flex items-center justify-between">
            <span className="text-sm font-medium text-gray-700">Increases</span>
            <span className="text-blue-600">📈</span>
          </div>
          <div className="mt-1 text-lg font-semibold text-gray-900">{formatCount(inc)}</div>
          <div className="text-xs text-gray-500">Price changes detected</div>
        </div>

        <div className="p-3 rounded-lg border border-gray-100">
          <div className="flex items-center justify-between">
            <span className="text-sm font-medium text-gray-700">Duplicates</span>
            <span className="text-gray-600">🧩</span>
          </div>
          <div className="mt-1 text-lg font-semibold text-gray-900">{formatCount(dup)}</div>
          <div className="text-xs text-gray-500">Potential overlaps found</div>
        </div>

        <div className="p-3 rounded-lg border border-gray-100">
          <div className="flex items-center justify-between">
            <span className="text-sm font-medium text-gray-700">Net Spend (est.)</span>
            <span className="text-gray-600">💼</span>
          </div>
          <div className="mt-1 text-lg font-semibold text-gray-900">
            {typeof spend === 'number' && typeof savings === 'number'
              ? currency(Math.max(0, spend - savings))
              : '—'}
            <span className="text-sm text-gray-500">/mo</span>
          </div>
          <div className="text-xs text-gray-500">After potential savings</div>
        </div>
      </div>
    </div>
  );
};

